function validate(input) {
  const [queryMultiple, t, calls] = input;
  if (!queryMultiple || typeof queryMultiple !== 'object' || Array.isArray(queryMultiple)) return 'queryMultiple must be an object { delay, perKey }.';
  const { delay, perKey } = queryMultiple;
  if (!Number.isInteger(delay) || delay < 0 || delay > 1000) return 'queryMultiple.delay must be an integer from 0 to 1000.';
  if (!Number.isInteger(perKey) || perKey < 0 || perKey > 200) return 'queryMultiple.perKey must be an integer from 0 to 200.';
  if (!Number.isInteger(t) || t < 0 || t > 1000) return 't must be an integer from 0 to 1000.';
  if (!Array.isArray(calls) || calls.length > 10) return 'Give at most 10 calls.';
  const keys = new Set();
  let previous = 0;
  for (const call of calls) {
    if (!call || typeof call !== 'object' || typeof call.key !== 'string' || !/^[a-z]{1,10}$/.test(call.key)) return 'Each call needs a key of 1 to 10 lowercase letters.';
    if (keys.has(call.key)) return `The key "${call.key}" appears twice; keys must be distinct.`;
    keys.add(call.key);
    if (!Number.isInteger(call.time) || call.time < 0 || call.time > 1000) return 'Each call needs a time from 0 to 1000.';
    if (call.time < previous) return 'List the calls in time order.';
    previous = call.time;
  }
  // Follow the rules: a call at the exact end of a waiting period would make the order ambiguous.
  let windowEnd = -1;
  let waiting = 0;
  for (const call of calls) {
    while (waiting > 0 && windowEnd < call.time) {
      windowEnd += t;
      waiting = 0;
    }
    if (call.time === windowEnd) return `getValue("${call.key}") at ${call.time} ms lands exactly t ms after a call of queryMultiple; move it by 1 ms.`;
    if (call.time > windowEnd) windowEnd = call.time + t;
    else waiting++;
  }
  return null;
}

