function adapt(input, solve, kit) {
  const [queryMultiple, t, calls] = input;
  const requested = new Set(), sent = new Set(), results = [];
  let lastQuery = null, failure = null;
  const fail = (message) => { failure = failure ?? message; };
  const query = (keys) => {
    const now = Date.now();
    if (!Array.isArray(keys)) {
      fail('queryMultiple must be called with an array of keys.');
      return Promise.resolve([]);
    }
    if (lastQuery !== null && now - lastQuery < t) fail(`queryMultiple was called at ${now} ms, only ${now - lastQuery} ms after its call at ${lastQuery} ms; calls must be at least t = ${t} ms apart.`);
    lastQuery = now;
    for (const key of keys) {
      if (!requested.has(key)) fail(`queryMultiple received "${key}", which no getValue call has asked for yet.`);
      else if (sent.has(key)) fail(`queryMultiple received "${key}" a second time; send each key once.`);
      sent.add(key);
    }
    const list = keys.map((key) => JSON.stringify(key)).join(', ');
    kit.trace(`queryMultiple([${list}]) is called`);
    const values = keys.map((key) => key + '!');
    const wait = queryMultiple.delay + queryMultiple.perKey * keys.length;
    if (wait === 0) return Promise.resolve(values);
    return new Promise((resolve) => setTimeout(() => {
      kit.trace(`queryMultiple([${list}]) resolves`);
      resolve(values);
    }, wait));
  };
  const batcher = new solve(query, t);
  if (!batcher || typeof batcher.getValue !== 'function') throw new Error('QueryBatcher needs a method getValue.');
  calls.forEach((call, index) => {
    setTimeout(() => {
      kit.trace(`getValue("${call.key}") is called`);
      requested.add(call.key);
      const promise = batcher.getValue(call.key);
      if (!promise || typeof promise.then !== 'function') {
        fail(`getValue("${call.key}") must return a promise.`);
        return;
      }
      promise.then((value) => {
        kit.trace(`getValue("${call.key}") resolves with ${JSON.stringify(value)}`);
        results.push({ resolved: value === undefined ? null : value, time: Date.now(), index });
      });
    }, call.time);
  });
  // The last batch starts at most t ms after the last call, then takes its query time.
  const lastCall = calls.length ? calls[calls.length - 1].time : 0;
  const end = lastCall + t + queryMultiple.delay + queryMultiple.perKey * calls.length + 1;
  return new Promise((resolve, reject) => setTimeout(() => {
    if (failure) return reject(new Error(failure));
    if (results.length < calls.length) {
      const done = new Set(results.map((result) => result.index));
      const missing = calls.find((_, index) => !done.has(index));
      return reject(new Error(`getValue("${missing.key}") had not resolved by ${end} ms, long after its batch should have finished.`));
    }
    results.sort((a, b) => a.time - b.time || a.index - b.index);
    resolve(results.map(({ resolved, time }) => ({ resolved, time })));
  }, end));
}

