class QueryBatcher {
  constructor(queryMultiple, t) {
    this.queryMultiple = queryMultiple;
    this.t = t;
    this.waiting = [];
    this.cooling = false;
  }

  getValue(key) {
    return new Promise((resolve) => {
      this.waiting.push({ key, resolve });
      if (!this.cooling) {
        this.flush();
      }
    });
  }

  flush() {
    if (this.waiting.length === 0) {
      this.cooling = false;
      return;
    }
    const batch = this.waiting;
    this.waiting = [];
    this.cooling = true;
    const keys = batch.map((item) => item.key);
    this.queryMultiple(keys).then((values) => {
      batch.forEach((item, i) => item.resolve(values[i]));
    });
    setTimeout(() => this.flush(), this.t);
  }
}

