class QueryBatcher {
  constructor(queryMultiple, t) {
    this.queryMultiple = queryMultiple;
    this.t = t;
    this.lastQuery = -Infinity;
    this.pending = null;
  }

  // Compare clock times instead of keeping a cooldown timer; one shared batch collects the keys that must wait.
  async getValue(key) {
    const now = Date.now();
    if (this.pending === null && now - this.lastQuery >= this.t) {
      this.lastQuery = now;
      const values = await this.queryMultiple([key]);
      return values[0];
    }
    if (this.pending === null) {
      const pending = { keys: [], result: null };
      pending.result = new Promise((resolve) => {
        setTimeout(() => {
          this.pending = null;
          this.lastQuery = Date.now();
          resolve(this.queryMultiple(pending.keys));
        }, this.lastQuery + this.t - now);
      });
      this.pending = pending;
    }
    const pending = this.pending;
    const index = pending.keys.push(key) - 1;
    const values = await pending.result;
    return values[index];
  }
}

