function generate(rand, size) {
  const small = size === 'small';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  for (;;) {
    const t = rand() < 0.1 ? 0 : Math.floor(rand() * (small ? 60 : 1001));
    const queryMultiple = {
      delay: rand() < 0.4 ? 0 : Math.floor(rand() * (small ? 80 : 1001)),
      perKey: rand() < 0.4 ? 0 : Math.floor(rand() * (small ? 40 : 201)),
    };
    const count = small ? Math.floor(rand() * 7) : 10;
    const calls = [], used = new Set();
    let time = Math.floor(rand() * (small ? 20 : 100));
    for (let i = 0; i < count && time <= 1000; i++) {
      let key = '';
      while (key === '' || used.has(key)) {
        key = Array.from({ length: 1 + Math.floor(rand() * (small ? 2 : 10)) }, () => letters[Math.floor(rand() * 26)]).join('');
      }
      used.add(key);
      calls.push({ key, time });
      const roll = rand();
      time += roll < 0.15 ? 0 : Math.floor(rand() * (small ? 40 : 250));
    }
    // Retry when a call lands exactly where a waiting period ends.
    let windowEnd = -1, waiting = 0, clash = false;
    for (const call of calls) {
      while (waiting > 0 && windowEnd < call.time) {
        windowEnd += t;
        waiting = 0;
      }
      if (call.time === windowEnd) clash = true;
      if (call.time > windowEnd) windowEnd = call.time + t;
      else waiting++;
    }
    if (!clash) return [queryMultiple, t, calls];
  }
}
